<?php
namespace App\Http\Controllers;
use App\Models\ChartOfAccount;use App\Models\GoodsReceipt;use App\Models\Product;use App\Models\Store;use App\Models\StorePosition;use App\Models\Supplier;use App\Services\AccountingPostingService;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\View\View;
class GoodsReceiptController extends Controller {
 public function index(Request $request):View{$f=$request->validate(['supplier'=>['nullable','integer'],'store'=>['nullable','integer'],'from'=>['nullable','date'],'to'=>['nullable','date'],'search'=>['nullable','string']]);$receipts=GoodsReceipt::query()->leftJoin('suppliers','goods_receipts.supplier_id','=','suppliers.id')->leftJoin('stores','goods_receipts.store_id','=','stores.id')->select('goods_receipts.*','suppliers.name as supplier_name','stores.name as store_name')->when($f['supplier']??null,fn($q,$v)=>$q->where('supplier_id',$v))->when($f['store']??null,fn($q,$v)=>$q->where('store_id',$v))->when($f['from']??null,fn($q,$v)=>$q->whereDate('mrr_date','>=',$v))->when($f['to']??null,fn($q,$v)=>$q->whereDate('mrr_date','<=',$v))->when($f['search']??null,fn($q,$v)=>$q->where('mrr_no','like',"%{$v}%"))->latest('mrr_date')->paginate(20)->withQueryString();return view('goods-receipts.index',['receipts'=>$receipts,'filters'=>$f,'suppliers'=>Supplier::where('is_active',true)->orderBy('name')->get(),'stores'=>Store::where('is_active',true)->orderBy('name')->get()]);}
 public function create():View{$cashAccountParentIds=ChartOfAccount::query()->whereIn('code',['1000101','1000102','1000103'])->pluck('id');return view('goods-receipts.showroom-create',['nextNo'=>$this->next(),'suppliers'=>Supplier::where('is_active',true)->orderBy('name')->get(),'stores'=>Store::where('is_active',true)->orderBy('name')->get(),'positions'=>StorePosition::where('is_active',true)->orderBy('name')->get(),'products'=>Product::where('is_active',true)->orderBy('part_no')->get(['id','part_no','name','unit']),'cashAccounts'=>ChartOfAccount::query()->where('is_active',true)->where('is_transactional',true)->where('account_type','asset')->where(fn($query)=>$query->whereIn('id',$cashAccountParentIds)->orWhereIn('parent_id',$cashAccountParentIds))->orderBy('code')->get(['id','code','name'])]);}
 public function store(Request $r){$d=$r->validate(['mrr_date'=>['required','date'],'payment_mode'=>['required','in:cash,bank,credit'],'cash_account_id'=>['nullable','integer','exists:chart_of_accounts,id'],'paid_amount'=>['nullable','numeric','min:0'],'purchase_type'=>['required','string'],'currency'=>['required','string'],'exchange_rate'=>['required','numeric','min:0'],'store_id'=>['required','exists:stores,id'],'supplier_id'=>['required','exists:suppliers,id'],'po_no'=>['nullable','string'],'remarks'=>['nullable','string'],'items'=>['required','array','min:1'],'items.*.product_id'=>['required','distinct','exists:products,id'],'items.*.store_position_id'=>['nullable','exists:store_positions,id'],'items.*.quantity'=>['required','numeric','min:.01'],'items.*.rate'=>['required','numeric','min:0']]);$total=(float)collect($d['items'])->sum(fn($x)=>(float)$x['quantity']*(float)$x['rate']);$paid=(float)($d['paid_amount']??0);if($paid>$total)return back()->withInput()->withErrors(['paid_amount'=>'Paid amount cannot exceed the total purchase amount.']);if($d['payment_mode']==='credit'&&$paid>0)return back()->withInput()->withErrors(['paid_amount'=>'Credit purchase cannot have a paid amount. Select Cash or Bank for an immediate payment.']);if($paid>0&&!$d['cash_account_id'])return back()->withInput()->withErrors(['cash_account_id'=>'Select the Cash or Bank account used for this payment.']);$cash=$paid>0?ChartOfAccount::query()->whereKey($d['cash_account_id'])->where('is_active',true)->where('is_transactional',true)->where('account_type','asset')->firstOrFail():null;DB::transaction(function()use($d,$r,$total,$paid,$cash){$g=GoodsReceipt::create(collect($d)->except('items')->all()+['mrr_no'=>$this->next(),'cash_head'=>$cash?->code.' — '.$cash?->name,'total_amount'=>$total,'paid_amount'=>$paid,'user_id'=>$r->user()->id]);$g->items()->createMany(collect($d['items'])->map(fn($x)=>$x+['amount'=>$x['quantity']*$x['rate'],'landed_cost'=>$x['rate']*$d['exchange_rate']])->all());app(AccountingPostingService::class)->postGoodsReceipt($g->load('supplier'),$cash,$r->user());});return redirect()->route('goods-receipts.index')->with('success','Goods received, payment recorded, and supplier due updated successfully.');}
 public function export(GoodsReceipt $receipt):View{$receipt=GoodsReceipt::findOrFail($receipt->id);$supplier=Supplier::find($receipt->supplier_id);$store=Store::find($receipt->store_id);$items=DB::table('goods_receipt_items as item')->leftJoin('products as product','item.product_id','=','product.id')->leftJoin('store_positions as position','item.store_position_id','=','position.id')->where('item.goods_receipt_id',$receipt->id)->select('item.*','product.part_no','product.name as product_name','product.unit','position.name as position_name')->get();return view('goods-receipts.export',compact('receipt','supplier','store','items'));}
 private function next():string{return 'MRR-'.now()->format('ymd').'-'.str_pad((string)(GoodsReceipt::whereDate('created_at',now()->toDateString())->count()+1),4,'0',STR_PAD_LEFT);}}
